# Probe for any additional data files (key, transcript, ciphertext) that might make this solvable offline.
import os

candidates = [
    "flag", "flag.txt", "server_ecdh_private.textproto", "server_ecdh_private",
    "key", "key.textproto", "private", "transcript", "capture.pcap", "output.txt",
    "server_hello", "hello.bin", "data.bin", "sample.bin", "README", "README.md",
    "encrypted_flag", "enc_flag", "server.key", "priv.key", "challenge",
]

found = {}
for name in candidates:
    try:
        with open(name, "rb") as f:
            data = f.read(4096)
        found[name] = data
    except Exception as e:
        pass

print("Files found among candidates:")
if not found:
    print("  (none)")
for name, data in found.items():
    print(f"--- {name} ({len(data)} bytes shown) ---")
    try:
        print(repr(data[:500]))
    except Exception:
        print(data[:200])
